}

entries.goodExample:
int count_nodes(const struct node *p) {
    int count = 0;
    for (; p != NULL && count < MAX_NODES; ++count)
        p = p->next;
    return p == NULL ? count : ERROR;
}

for (unsigned int i = 0; i < MAX_POLLS; ++i) {
