entries.badExample:
int consume(struct queue *q) {
    assert(q->count-- > 0);
    return q->items[q->count];
}

entries.goodExample:
int consume(struct queue *q) {
    if (!c_assert(q != NULL)) return ERROR;
    if (!c_assert(q->count > 0 && q->count <= CAPACITY)) return ERROR;
    --q->count;
    return q->items[q->count];
}

