entries.goodExample:
/* header 直接内嵌在消息中 */
struct message { struct header header; };
size_t frame_length(const struct message *message) {
    return message->header.length;
}

int execute(enum operation operation, int value) {
    switch (operation) {
    case OP_ENCODE: return encode(value);
    case OP_DECODE: return decode(value);
    default: return ERROR;
    }
}
